"""Hosted A-share lookup over native symbol search and a fixed Tencent supplement."""
import json
import logging
import os
import re

from fastapi import Depends, FastAPI, HTTPException, Request
from starlette.concurrency import run_in_threadpool
from src.api.security import require_auth
from src.tools.symbol_search_tool import _search_eastmoney
from backtest.loaders._http import throttled_get

_LOG = logging.getLogger(__name__)
_EXCHANGES = (("SH", r"(?:600|601|603|605|688)[0-9]{3}"),
              ("SZ", r"(?:000|001|002|003|300|301)[0-9]{3}"),
              ("BJ", r"(?:43|83|87|92)[0-9]{4}"))


def _candidates(rows):
    result, seen = [], set()
    for row in rows:
        symbol, name = row.get("symbol", ""), row.get("name")
        if not isinstance(symbol, str) or not isinstance(name, str) or not 1 <= len(name.strip()) <= 128:
            continue
        code, _, suffix = symbol.partition(".")
        exchange = next((venue for venue, pattern in _EXCHANGES if re.fullmatch(pattern, code)), None)
        # Native Eastmoney maps market 0 to SZ, including Beijing equities.
        if exchange == "BJ" and suffix == "SZ" and row.get("type") in {"北A", "京A"}:
            suffix = "BJ"
        if exchange is None or suffix != exchange:
            continue
        symbol = f"{code}.{exchange}"
        if symbol not in seen:
            seen.add(symbol)
            result.append({"symbol": symbol, "name": name.strip()})
    return result[:10]


def _tencent_search(query):
    response = throttled_get("https://smartbox.gtimg.cn/s3/", host_key="tencent",
                             min_interval=1.0, params={"q": query, "t": "gp"}, timeout=8, allow_redirects=False)
    response.raise_for_status()
    if len(response.content) > 128_000:
        raise ValueError("search response too large")
    match = re.fullmatch(r'\s*v_hint=("[^\r\n]*");?\s*', response.content.decode("utf-8"))
    if match is None:
        raise ValueError("unexpected search response")
    content = json.loads(match[1])
    rows = []
    for item in content.split("^"):
        parts = item.split("~")
        if len(parts) >= 5 and parts[0] in {"sh", "sz", "bj"} and parts[4] == "GP-A":
            rows.append({"symbol": f"{parts[1]}.{parts[0].upper()}", "name": parts[2]})
    return rows


def search_symbols(query):
    rows, status = _search_eastmoney(query)
    source = "eastmoney"
    if status != "ok":
        _LOG.warning("Native Eastmoney symbol search unavailable; using Tencent")
        try:
            rows = _tencent_search(query)
            source = "tencent"
        except Exception as exc:
            _LOG.warning("Symbol search unavailable (%s)", type(exc).__name__)
            raise HTTPException(502, "symbol search unavailable") from None
    return {"query": query, "candidates": _candidates(rows), "source": source}


def register_mona_symbol_search(app: FastAPI):
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/symbol-search", dependencies=[Depends(require_auth)])
    async def search(request: Request, q: str):
        if set(request.query_params) != {"q"} or len(request.query_params.getlist("q")) != 1:
            raise HTTPException(422, "unsupported search fields")
        q = q.strip()
        if not 1 <= len(q) <= 40 or any(ord(char) < 32 for char in q):
            raise HTTPException(422, "invalid search query")
        return await run_in_threadpool(search_symbols, q)
